# Don't build a universal ontology; bind semantic definitions directly to destination execution boundaries
def execute_agent_action(intent, agent_claims):
    # 1. Resolve term strictly within the target system's dialect, not a shared global model
    semantic_contract = registry.get_contract(target=intent.destination, concept=intent.concept)
    # 2. Compile row/column entitlements into deterministic filter ASTs rather than relying on tool-level scopes
    data_guardrails = policy_engine.compile_filters(agent_claims, semantic_contract.required_policies)
    # 3. Synthesize downstream query/payload deterministically so the agent never constructs raw semantic queries
    bound_payload = semantic_contract.bind(intent.parameters, predicates=data_guardrails)
    # 4. Reject execution if target schema version drifted or semantic predicates cannot be proven safe
    if not bound_payload.is_provably_safe():
        return abort_with_audit_trail(intent, reason="Semantic ambiguity or policy breach")
    # 5. Dispatch as a signed, stateless execution bundle through an ephemeral gateway
    return gateway.dispatch(intent.destination_tool, bound_payload.to_signed_token())
